    def f1_score(y_true, y_pred, average='macro'):
        classes = sorted(set(y_true) | set(y_pred))
        f1s = []
        for c in classes:
            tp = sum(1 for t, p in zip(y_true, y_pred) if t == c and p == c)
            fp = sum(1 for t, p in zip(y_true, y_pred) if t != c and p == c)
            fn = sum(1 for t, p in zip(y_true, y_pred) if t == c and p != c)
            prec = tp / (tp + fp) if (tp + fp) > 0 else 0
            rec = tp / (tp + fn) if (tp + fn) > 0 else 0
            f1 = 2 * prec * rec / (prec + rec) if (prec + rec) > 0 else 0
            f1s.append(f1)
        return np.mean(f1s)

def compute_recalls(preds_list, labels_list):
    preds = np.array(preds_list)
    labels = np.array(labels_list)
    attack_mask = labels == 1
    benign_mask = labels == 0
    attack_recall = float(np.mean(preds[attack_mask] == 1)) if attack_mask.sum() > 0 else None
    benign_recall = float(np.mean(preds[benign_mask] == 0)) if benign_mask.sum() > 0 else None
    return round(attack_recall, 6) if attack_recall is not None else None, \
           round(benign_recall, 6) if benign_recall is not None else None

