            preds = dd_preds["preds"]["binary"][seed]["full"]
            per_seed_f1["Binary"]["DD"][int(seed)] = round(f1_score(dd_labels, preds, average='macro'), 6)

# Scrambled DD: from plan/mf1 files
scr_s42 = load_json(RESULTS / "plan_003_scrambled_fix.json")
per_seed_f1["Scrambled"]["DD"][42] = round(scr_s42["dd_ood_results"]["full"]["f1_macro"], 6)
scr_s123 = load_json(RESULTS / "mf1_scrambled_seed123.json")
per_seed_f1["Scrambled"]["DD"][123] = round(scr_s123["dd_ood_results"]["full"]["f1_macro"], 6)
scr_s456 = load_json(RESULTS / "mf1_scrambled_seed456.json")
per_seed_f1["Scrambled"]["DD"][456] = round(scr_s456["dd_ood_results"]["full"]["f1_macro"], 6)

