def cohens_d(x, y):
    mx, my = np.mean(x), np.mean(y)
    sx, sy = np.std(x, ddof=0), np.std(y, ddof=0)
    pooled = np.sqrt((sx**2 + sy**2) / 2)
    if pooled == 0:
        return float('inf') if mx != my else 0.0
    return (mx - my) / pooled

